KANA_WORD = re.compile(r"^[ぁ-んァ-ンー]{2,4}$")
KANA = "あいうえおかきくけこさしすせそたちつてとなにぬねのはひふへほまみむめもやゆよらりるれろわをん"
VOWELS = "あいうえお"
ROWS = ["かきくけこ", "がぎぐげご", "さしすせそ", "ざじずぜぞ", "たちつてと", "だぢづでど", "なにぬねの", "はひふへほ", "ばびぶべぼ", "ぱぴぷぺぽ", "まみむめも", "らりるれろ"]
GOJUON_ROWS = ["あいうえお", "かきくけこ", "がぎぐげご", "さしすせそ", "ざじずぜぞ", "たちつてと", "だぢづでど", "なにぬねの", "はひふへほ", "ばびぶべぼ", "ぱぴぷぺぽ", "まみむめも", "やゆよ", "らりるれろ", "わをん"]
ORDERED_SETS = {
    "曜日": ["げつ", "か", "すい", "もく", "きん", "ど", "にち"],
    "十二支": ["ね", "うし", "とら", "う", "たつ", "み", "うま", "ひつじ", "さる", "とり", "いぬ", "い"],
    "四季": ["はる", "なつ", "あき", "ふゆ"],
    "数字": ["いち", "に", "さん", "し", "ご", "ろく", "しち", "はち", "きゅう", "じゅう"],
    "松竹梅": ["まつ", "たけ", "うめ"],
}
DAKUTEN = dict(zip("かきくけこさしすせそたちつてとはひふへほ", "がぎぐげござじずぜぞだぢづでどばびぶべぼ"))
DAKUTEN.update({v: k for k, v in list(DAKUTEN.items())})
HANDAKUTEN = dict(zip("はひふへほ", "ぱぴぷぺぽ"))
HANDAKUTEN.update({v: k for k, v in list(HANDAKUTEN.items())})


def build_dictionary(words):
    return {w.strip() for w in words if isinstance(w, str) and KANA_WORD.fullmatch(w.strip())}


def load_word_list():
    return build_dictionary(WORD_LIST)


def replace_at(word, index, table):
    return word[:index] + table[word[index]] + word[index + 1:] if word[index] in table else None


def replacements(word, table):
    result = []
    for i in range(len(word)):
        value = replace_at(word, i, table)
        if value:
            result.append(value)
    return result


def gojuon_shift(word):
    result = []
    for direction in (-1, 1):
        shifted = []
        valid = True
        for char in word:
            row = next((values for values in GOJUON_ROWS if char in values), None)
            if row is None:
                valid = False
                break
            shifted.append(row[(row.index(char) + direction) % len(row)])
        if valid:
            result.append("".join(shifted))
    return result


def ordered_next(word):
    """順序表の隣の要素へ1つ進める。表の途中から始めてもよい。"""
    return [values[index + 1] for values in ORDERED_SETS.values() for index, value in enumerate(values[:-1]) if value == word]


def rules():
    return [
        ("先頭1文字削除", lambda w: [w[1:]] if len(w) >= 3 else []),
        ("末尾1文字削除", lambda w: [w[:-1]] if len(w) >= 3 else []),
        ("中間1文字削除", lambda w: [w[:i] + w[i + 1:] for i in range(1, len(w) - 1)] if len(w) >= 3 else []),
        ("先頭1文字追加", lambda w: [c + w for c in KANA] if len(w) < 4 else []),
        ("末尾1文字追加", lambda w: [w + c for c in KANA] if len(w) < 4 else []),
        ("中間1文字追加", lambda w: [w[:i] + c + w[i:] for i in range(1, len(w)) for c in KANA] if len(w) < 4 else []),
        ("先頭文字置換", lambda w: [c + w[1:] for c in KANA]),
        ("末尾文字置換", lambda w: [w[:-1] + c for c in KANA]),
        ("中間文字置換", lambda w: [w[:i] + c + w[i + 1:] for i in range(1, len(w) - 1) for c in KANA] if len(w) >= 3 else []),
        ("濁点・清音変換", lambda w: replacements(w, DAKUTEN)),
        ("半濁点変換", lambda w: replacements(w, HANDAKUTEN)),
        ("母音変換", lambda w: [w[:i] + v + w[i + 1:] for i, ch in enumerate(w) if ch in VOWELS for v in VOWELS if v != ch]),
        ("子音スライド", lambda w: [w[:i] + c + w[i + 1:] for i, ch in enumerate(w) for row in ROWS if ch in row for c in row if c != ch]),
        ("五十音シフト", gojuon_shift),
        ("外部規則・順序", ordered_next),
        ("逆読み", lambda w: [w[::-1]]),
        ("並び替え", lambda w: ["".join(p) for p in permutations(w) if "".join(p) not in {w, w[::-1]}]),
    ]


def search_pairs(dictionary):
    found, seen = [], set()
    for word in sorted(dictionary):
        for name, transform in rules():
            for answer in transform(word):
                group = rule_group(word, answer, name)
                key = (word, answer, group)
                if answer in dictionary and answer != word and key not in seen:
                    seen.add(key)
                    found.append({"source": word, "answer": answer, "rule": name, "rule_group": group})
    return found


def rule_group(source, answer, name):
    """問題として同じ規則と呼べる位置・変化要素まで含めたグループを返す。"""
    if name in {"先頭1文字削除", "末尾1文字削除"}:
        return name
    if name == "中間1文字削除":
        for index in range(1, len(source) - 1):
            if source[:index] + source[index + 1:] == answer:
                return f"{name}:{index}"
    if name == "先頭1文字追加":
        return f"{name}:{answer[0]}"
    if name == "末尾1文字追加":
        return f"{name}:{answer[-1]}"
    if name == "中間1文字追加":
        for index in range(1, len(source)):
            if answer[:index] == source[:index] and answer[index + 1:] == source[index:]:
                return f"{name}:{index}:{answer[index]}"
    if name == "先頭文字置換":
        return f"{name}:{source[0]}→{answer[0]}"
    if name == "末尾文字置換":
        return f"{name}:{source[-1]}→{answer[-1]}"
    if name == "中間文字置換":
        for index in range(1, len(source) - 1):
            if source[:index] == answer[:index] and source[index + 1:] == answer[index + 1:]:
                return f"{name}:{index}:{source[index]}→{answer[index]}"
    if name in {"母音変換", "子音スライド"}:
        for index, (before, after) in enumerate(zip(source, answer)):
            if before != after:
                return f"{name}:{index}:{before}→{after}"
    if name in {"濁点・清音変換", "半濁点変換"}:
        for index, (before, after) in enumerate(zip(source, answer)):
            if before != after:
                return f"{name}:{index}"
    if name == "外部規則・順序":
        for set_name, values in ORDERED_SETS.items():
            if any(values[index] == source and values[index + 1] == answer for index in range(len(values) - 1)):
                return f"{name}:{set_name}"
    return name


def edit_distance(a, b):
    row = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        previous, row[0] = row[0], i
        for j, y in enumerate(b, 1):
            saved = row[j]
            row[j] = min(row[j] + 1, row[j - 1] + 1, previous + (x != y))
            previous = saved
    return row[-1]


def judge(source, answer):
    distance = edit_distance(source, answer)
    score = max(0, round((1 - distance / max(len(source), len(answer))) * 100))
    return {"score": score, "distance": distance, "result": "採用" if score >= 50 else "除外"}


def fallback(pairs, constraints=None):
    groups = {}
    for pair in pairs:
        groups.setdefault(pair.get("rule_group", pair["rule"]), []).append(pair)
    available = [items for items in groups.values() if len(items) >= 3]
    if constraints:
        available = [items for items in available if any((not constraints.get("source") or p["source"] == constraints["source"]) and (not constraints.get("answer") or p["answer"] == constraints["answer"]) for p in items)]
    if not available:
        raise ValueError("入力条件と同じ規則で成立する単語ペアが見つかりません")
    group = random.choice(available)
    candidates = [p for p in group if not constraints or ((not constraints.get("source") or p["source"] == constraints["source"]) and (not constraints.get("answer") or p["answer"] == constraints["answer"]))]
    main = random.choice(candidates or group)
    examples = random.sample([p for p in group if p["source"] != main["source"]], 2)
    return {"title": "生成された謎", "problem": [f"{p['source']} → {p['answer']}" for p in examples] + [f"{main['source']} → ？"], "answer": main["answer"], "rule": main["rule"], "hints": ["矢印の前後で、文字の位置・数・音の変化を比べてみよう。", f"元の単語は{len(main['source'])}文字、答えは{len(main['answer'])}文字です。", f"例題の「{examples[0]['source']}」にも同じ規則が使われています。"], "explanation": f"「{main['source']}」に「{main['rule']}」を適用すると「{main['answer']}」になります。", "judgement": judge(main["source"], main["answer"])}


def ai_generate(pairs, theme="", constraints=None):
    print("⑤ AIに問題・ヒント・解説の生成を依頼しています...", flush=True)
    key = API_KEY
    if not key:
        print("⑤ APIキーがないため、自動生成に切り替えます。", flush=True)
        return [fallback(pairs, constraints)], False
    groups = {}
    for pair in pairs:
        groups.setdefault(pair.get("rule_group", pair["rule"]), []).append(pair)
    groups = {rule: items[:40] for rule, items in groups.items() if len(items) >= 3}
    if not groups:
        return [fallback(pairs, constraints)], False
    prompt = {"pairs_by_rule_group": groups, "constraints": constraints or {}, "theme": theme or "指定なし", "request": "constraintsを最優先してください。sourceが指定されたらその単語を3行目の元単語にし、answerが指定されたらその単語を3行目の答えにしてください。ruleが指定された場合はその規則だけを使ってください。themeが指定された場合は意味がテーマに近い単語ペアを優先してください。必ず1つのrule_groupだけを選んでください。rule_groupが同じペアは、位置と変化要素が一致しています。problemは空配列で返してください。ヒントは①文字数、②位置、③規則の順にしてください。JSONのみで返してください。", "format": {"title": "空文字列", "rule_group": "文字列", "answer_source": "文字列", "problem": [], "hints": ["文字数のヒント", "位置のヒント", "規則のヒント"], "answer": "文字列", "explanation": "文字列"}}
    body = json.dumps({"contents": [{"parts": [{"text": json.dumps(prompt, ensure_ascii=False)}]}], "generationConfig": {"responseMimeType": "application/json"}}).encode()
    model = os.environ.get("GEMINI_MODEL", "gemini-3.7-flash")
    request = Request(f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent", data=body, headers={"Content-Type": "application/json", "x-goog-api-key": key}, method="POST")
    with urlopen(request, timeout=45) as response:
        data = json.load(response)
    puzzle = json.loads(data["candidates"][0]["content"]["parts"][0]["text"])
    selected_group = puzzle.get("rule_group", "")
    selected = next((p for p in groups.get(selected_group, []) if p["source"] == puzzle.get("answer_source") and p["answer"] == puzzle.get("answer") and (not constraints or not constraints.get("source") or p["source"] == constraints["source"]) and (not constraints or not constraints.get("answer") or p["answer"] == constraints["answer"])), None)
    if selected is None or len(puzzle.get("hints", [])) != 3:
        raise ValueError("AIの返却内容を検証できませんでした")
    example_pool = [pair for pair in groups[selected_group] if pair["source"] != selected["source"]]
    if len(example_pool) < 2:
        raise ValueError("同じ規則の例題が不足しています")
    examples = random.sample(example_pool, 2)
    puzzle["title"] = ""
    puzzle["problem"] = [f"{pair['source']} → {pair['answer']}" for pair in examples] + [f"{selected['source']} → ？"]
    puzzle["judgement"] = judge(selected["source"], selected["answer"])
    puzzle["rule"] = selected["rule"]
    puzzle_list = [puzzle]
    remaining = [pair for pair in groups[selected_group] if pair["source"] not in {selected["source"], examples[0]["source"], examples[1]["source"]}]
    for main in remaining[:4]:
        other = [pair for pair in groups[selected_group] if pair["source"] != main["source"]]
        if len(other) < 2:
            break
        sample_examples = random.sample(other, 2)
        puzzle_list.append({"title": "", "problem": [f"{pair['source']} → {pair['answer']}" for pair in sample_examples] + [f"{main['source']} → ？"], "answer": main["answer"], "rule": main["rule"], "hints": puzzle["hints"], "explanation": f"「{main['source']}」に「{main['rule']}」を適用すると「{main['answer']}」になります。", "judgement": judge(main["source"], main["answer"])})
    print("⑤ AI生成が完了しました。", flush=True)
    return puzzle_list, True


class Handler(BaseHTTPRequestHandler):
    def send_json(self, status, value):
        raw = json.dumps(value, ensure_ascii=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()
        self.wfile.write(raw)

    def do_OPTIONS(self):
        self.send_json(204, {})

    def do_GET(self):
        relative = self.path.lstrip("/") or "index.html"
        target = (ROOT / relative).resolve()
        if target.parent == ROOT and target.is_file() and target.suffix in {".html", ".js", ".json"}:
            raw = target.read_bytes()
            self.send_response(200)
            content_type = {".html": "text/html", ".js": "text/javascript", ".json": "application/json"}[target.suffix]
            self.send_header("Content-Type", content_type + "; charset=utf-8")
            self.end_headers()
            self.wfile.write(raw)
        else:
            self.send_json(404, {"error": "Not found"})

    def do_POST(self):
        if self.path != "/api/generate":
            self.send_json(404, {"error": "Not found"})
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            payload = json.loads(self.rfile.read(length))
            print("① 採用単語を受け取りました。", flush=True)
            received_words = payload.get("words", [])
            words = build_dictionary(received_words) if received_words else load_word_list()
            print(f"② 単語を精査しました: {len(words)}語", flush=True)
            pairs = search_pairs(words)
            source = str(payload.get("source", "")).strip()
            answer = str(payload.get("answer", "")).strip()
            requested_rule = str(payload.get("rule", "")).strip()
            constraints = {"source": source, "answer": answer, "rule": requested_rule if requested_rule != "自動" else "", "theme": str(payload.get("theme", "")).strip()}
            anchor = [pair for pair in pairs if (not source or pair["source"] == source) and (not answer or pair["answer"] == answer) and (not constraints["rule"] or pair["rule"] == constraints["rule"])]
            if source or answer:
                if not anchor:
                    raise ValueError("指定された単語で成立するペアが見つかりません")
            if requested_rule and requested_rule != "自動":
                pairs = [pair for pair in pairs if pair["rule"] == requested_rule]
            print(f"③ 規則を全種類適用しました: {len(pairs)}組", flush=True)
            if len(pairs) < 3:
                raise ValueError("成立する単語ペアが3組未満です")
            print("④ 成立する単語ペアを確認しました。", flush=True)
            puzzles, used = ai_generate(pairs, constraints.get("theme", ""), constraints)
            print("⑥ 判定結果を計算しました。", flush=True)
            self.send_json(200, {"puzzle": puzzles[0], "puzzles": puzzles, "wordCount": len(words), "pairCount": len(pairs), "aiUsed": used})
        except Exception as error:
            self.send_json(400, {"error": str(error)})


if __name__ == "__main__":
    print("① システムを起動しています...", flush=True)
    print("http://localhost:8000 で起動しました！")
    ThreadingHTTPServer(("localhost", 8000), Handler).serve_forever()

